int powermate_probe(struct usb_interface *intf, const struct usb_device_id *id) {
    struct usb_host_interface *iface_desc;
    struct usb_endpoint_descriptor *endpoint;
    struct usb_device *dev;
    int retval = -ENOMEM;

    iface_desc = intf->cur_altsetting;
    dev = interface_to_usbdev(intf);

    if (iface_desc->endpoint[0].desc.bDescriptorType != USB_DT_ENDPOINT) {
        dev_err(&dev->dev, "Invalid endpoint descriptor type\n");
        return -EINVAL;
    }

    endpoint = &iface_desc->endpoint[0].desc;

    if (!usb_endpoint_is_int_in(endpoint)) {
        dev_err(&dev->dev, "No interrupt IN endpoint found\n");
        return -EINVAL;
    }

    /* Allocate necessary resources and set up input device */
    struct powermate_device *pdev;
    pdev = kzalloc(sizeof(*pdev), GFP_KERNEL);
    if (!pdev)
        return -ENOMEM;

    pdev->input_dev = input_allocate_device();
    if (!pdev->input_dev)
        goto err_free_pdev;

    /* Configure interrupt URB and other device parameters */
    pdev->urb = usb_alloc_urb(0, GFP_KERNEL);
    if (!pdev->urb)
        goto err_free_input_dev;

    usb_fill_int_urb(pdev->urb, dev,
                     usb_rcvintpipe(dev, endpoint->bEndpointAddress),
                     pdev->data, sizeof(pdev->data),
                     powermate_irq, pdev, endpoint->bInterval);

    pdev->urb->transfer_flags |= URB_AUTO_ISO_ASAP;

    /* Set device name based on product ID */
    if (id->idVendor == 0x05a4 && id->idProduct == 0x9696) {
        strcpy(pdev->name, "Logitech PowerMate");
    } else {
        strcpy(pdev->name, "Unknown PowerMate Device");
    }

    pdev->pulse_period = 0;
    pdev->pulse_width = 0;

    /* Register input device */
    pdev->input_dev->name = pdev->name;
    pdev->input_dev->id.bustype = BUS_USB;
    pdev->input_dev->id.vendor = id->idVendor;
    pdev->input_dev->id.product = id->idProduct;
    pdev->input_dev->id.version = 0x0100;

    input_register_device(pdev->input_dev);

    usb_set_intfdata(intf, pdev);

    return 0;

err_free_input_dev:
    input_free_device(pdev->input_dev);
err_free_pdev:
    kfree(pdev);
    return retval;
}

int powermate_probe(struct usb_interface *intf, const struct usb_device_id *id) {
    struct usb_host_interface *iface_desc;
    struct usb_endpoint_descriptor *endpoint;
    struct powermate_dev *dev;
    int retval = -ENOMEM;

    iface_desc = intf->cur_altsetting;
    if (iface_desc->desc.bNumEndpoints != 1)
        return -ENODEV;

    endpoint = &iface_desc->endpoint[0].desc;
    if (!usb_endpoint_is_int_in(endpoint))
        return -ENODEV;

    dev = kzalloc(sizeof(*dev), GFP_KERNEL);
    if (!dev)
        return -ENOMEM;

    dev->udev = usb_get_dev(interface_to_usbdev(intf));
    dev->interface = intf;
    usb_set_intfdata(intf, dev);

    dev->input_dev = input_allocate_device();
    if (!dev->input_dev)
        goto err_free_dev;

    dev->urb = usb_alloc_urb(0, GFP_KERNEL);
    if (!dev->urb)
        goto err_free_input_dev;

    dev->buffer = kmalloc(POWERMATE_BUFFER_SIZE, GFP_KERNEL);
    if (!dev->buffer)
        goto err_free_urb;

    dev->input_dev->name = "Logitech PowerMate USB Wheel";
    dev->input_dev->id.bustype = BUS_USB;
    dev->input_dev->id.vendor = le16_to_cpu(dev->udev->descriptor.idVendor);
    dev->input_dev->id.product = le16_to_cpu(dev->udev->descriptor.idProduct);
    dev->input_dev->id.version = 0x0100;
    dev->input_dev->evbit[0] = BIT_MASK(EV_REL);
    dev->input_dev->rel.bit[0] = BIT_MASK(REL_WHEEL);

    input_register_device(dev->input_dev);

    usb_fill_int_urb(dev->urb, dev->udev,
                     usb_rcvintpipe(dev->udev, endpoint->bEndpointAddress),
                     dev->buffer, POWERMATE_BUFFER_SIZE,
                     powermate_irq, dev, endpoint->bInterval);

    if (usb_submit_urb(dev->urb, GFP_KERNEL) < 0)
        goto err_unregister_dev;

    dev->pulse_period = 100;
    dev->pulse_width = 50;

    return 0;

err_unregister_dev:
    input_unregister_device(dev->input_dev);
err_free_urb:
    usb_free_urb(dev->urb);
err_free_input_dev:
    input_free_device(dev->input_dev);
err_free_dev:
    kfree(dev->buffer);
    kfree(dev);
    return retval;
}

int powermate_probe(struct usb_interface *intf, const struct usb_device_id *id) {
    struct usb_host_interface *iface_desc;
    struct usb_endpoint_descriptor *endpoint;
    struct powermate_dev *dev;
    int ret = -ENOMEM;

    iface_desc = intf->cur_altsetting;
    if (iface_desc->desc.bNumEndpoints != 1)
        return -ENODEV;

    endpoint = &iface_desc->endpoint[0].desc;
    if (!usb_endpoint_is_int_in(endpoint))
        return -ENODEV;

    dev = kzalloc(sizeof(*dev), GFP_KERNEL);
    if (!dev)
        return -ENOMEM;

    dev->usbdev = usb_get_dev(interface_to_usbdev(intf));
    dev->intf = intf;
    dev->input = input_allocate_device();
    if (!dev->input)
        goto free_dev;

    dev->urb = usb_alloc_urb(0, GFP_KERNEL);
    if (!dev->urb)
        goto free_input;

    dev->buf = kmalloc(PM_PACKET_SIZE, GFP_KERNEL);
    if (!dev->buf)
        goto free_urb;

    usb_fill_int_urb(dev->urb, dev->usbdev, usb_rcvintpipe(dev->usbdev, endpoint->bEndpointAddress),
                     dev->buf, PM_PACKET_SIZE, powermate_irq, dev, endpoint->bInterval);

    dev->input->evbit[0] = BIT_MASK(EV_REL) | BIT_MASK(EV_KEY);
    dev->input->keybit[BIT_WORD(BTN_MISC)] |= BIT_MASK(BTN_MISC);
    dev->input->relbit[0] = BIT_MASK(REL_WHEEL);

    snprintf(dev->input->name, sizeof(dev->input->name), "Griffin PowerMate");
    dev->input->id.bustype = BUS_USB;
    dev->input->id.vendor = le16_to_cpu(dev->usbdev->descriptor.idVendor);
    dev->input->id.product = le16_to_cpu(dev->usbdev->descriptor.idProduct);
    dev->input->id.version = 0x0001;

    dev->input->cdev.dev = &intf->dev;
    dev->input->open = powermate_open;
    dev->input->close = powermate_close;

    ret = input_register_device(dev->input);
    if (ret)
        goto free_buffer;

    usb_set_intfdata(intf, dev);
    return 0;

free_buffer:
    kfree(dev->buf);
free_urb:
    usb_free_urb(dev->urb);
free_input:
    input_free_device(dev->input);
free_dev:
    kfree(dev);
    return ret;
}

