    if (!pdev)
        return ret;

    iface_desc = intf->cur_altsetting;
    endpoint = &iface_desc->endpoint[0].desc;

    usb_fill_int_urb(pdev->urb, pdev->udev, usb_rcvintpipe(pdev->udev, endpoint->bEndpointAddress),
                     pdev->data, sizeof(pdev->data), powermate_irq, pdev, endpoint->bInterval);

    pdev->input_dev = input_allocate_device();
